export interface CacheOptions {
  maxEntries: number;
  ttlMs?: number;
  now?: () => number;
}

interface Entry<V> {
  value: V;
  expiresAt: number | null;
}

export class LruCache<K, V> {
  private readonly maxEntries: number;
  private readonly defaultTtl: number | null;
  private readonly nowFn: () => number;
  private readonly map: Map<K, Entry<V>>;

  constructor(options: CacheOptions) {
    const { maxEntries, ttlMs, now } = options;

    if (!Number.isInteger(maxEntries) || maxEntries < 1) {
      throw new RangeError("maxEntries must be an integer of 1 or more");
    }
    if (ttlMs !== undefined && (!Number.isFinite(ttlMs) || ttlMs <= 0)) {
      throw new RangeError("ttlMs must be a finite number greater than 0");
    }

    this.maxEntries = maxEntries;
    this.defaultTtl = ttlMs !== undefined ? ttlMs : null;
    this.nowFn = now ?? Date.now;
    this.map = new Map();
  }

  get(key: K): V | undefined {
    const entry = this.map.get(key);
    if (entry === undefined) return undefined;
    if (this.isExpired(entry)) {
      this.map.delete(key);
      return undefined;
    }
    // Promote to most-recently-used
    this.map.delete(key);
    this.map.set(key, entry);
    return entry.value;
  }

  set(key: K, value: V, ttlMs?: number): this {
    if (ttlMs !== undefined && (!Number.isFinite(ttlMs) || ttlMs <= 0)) {
      throw new RangeError("ttlMs must be a finite number greater than 0");
    }

    const existing = this.map.get(key);

    if (existing !== undefined && !this.isExpired(existing)) {
      // Replace an existing live entry – no eviction possible
      const expiresAt = this.computeExpiry(ttlMs);
      this.map.delete(key);
      this.map.set(key, { value, expiresAt });
      return this;
    }

    // Treat as a brand-new key (either truly new, or the stored entry was expired)
    if (existing !== undefined) {
      this.map.delete(key);
    }

    if (this.map.size >= this.maxEntries) {
      this.purgeExpired();
      if (this.map.size >= this.maxEntries) {
        // Evict the least-recently-used live entry (first in Map iteration order)
        const lruKey = this.map.keys().next().value as K;
        this.map.delete(lruKey);
      }
    }

    const expiresAt = this.computeExpiry(ttlMs);
    this.map.set(key, { value, expiresAt });
    return this;
  }

  has(key: K): boolean {
    const entry = this.map.get(key);
    if (entry === undefined) return false;
    if (this.isExpired(entry)) {
      this.map.delete(key);
      return false;
    }
    return true;
  }

  delete(key: K): boolean {
    const entry = this.map.get(key);
    if (entry === undefined) return false;
    if (this.isExpired(entry)) {
      this.map.delete(key);
      return false;
    }
    this.map.delete(key);
    return true;
  }

  clear(): void {
    this.map.clear();
  }

  get size(): number {
    this.purgeExpired();
    return this.map.size;
  }

  keys(): K[] {
    this.purgeExpired();
    // Map iterates least-recent → most-recent; spec wants most → least.
    return [...this.map.keys()].reverse();
  }

  // ── private helpers ──────────────────────────────────────────────

  private isExpired(entry: Entry<V>): boolean {
    return entry.expiresAt !== null && this.nowFn() >= entry.expiresAt;
  }

  private computeExpiry(ttlMs: number | undefined): number | null {
    const effectiveTtl = ttlMs !== undefined ? ttlMs : this.defaultTtl;
    return effectiveTtl !== null ? this.nowFn() + effectiveTtl : null;
  }

  private purgeExpired(): void {
    for (const [key, entry] of this.map) {
      if (this.isExpired(entry)) {
        this.map.delete(key);
      }
    }
  }
}
```

### How it works

**Storage** — A single `Map<K, Entry<V>>` is used. JavaScript `Map` preserves insertion order, so the *first* entry in iteration is the **least-recently-used** and the *last* is the **most-recently-used**. Every `get`/`set` on a live entry deletes and re-inserts the key, which moves it to the tail.

**Expiry** — Each entry stores an `expiresAt` timestamp (or `null` for no expiry). On every access the current time is compared via the injectable `now` function. Expired entries are treated as absent: they are lazily removed the first time they are encountered, and bulk-purged before eviction checks in `set` and before reporting `size`/`keys`.

**Eviction** — When `set` inserts a *new* key and the map is at capacity, all expired entries are purged first. If the map is still full, the LRU entry (front of the map) is evicted. Replacing an existing live key never triggers eviction.

**Complexity** — `get`, `set`, `has`, `delete`, `clear` are all **O(1)** amortised. `keys` and `size` are **O(n)** in the worst case (when many expired entries must be purged).

